import { createHash, randomUUID } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import type { MemeMime, MemePopPayload } from '../../shared/types'
import { MEME_MAX_DURATION_MS, MEME_MIN_DURATION_MS } from '../../shared/types'
import type { MemeStore, StoredMeme } from '../db/memes'

/**
 * File names are generated by the app, never taken from the upload. The
 * pattern is checked before any filesystem access, so a request can never
 * point outside the meme folder.
 */
export const MEME_FILE_PATTERN = /^[0-9a-f-]{16,64}\.(jpg|png)$/

/** The largest compressed image the app stores. */
export const MEME_MAX_BYTES = 2 * 1024 * 1024

/** The folder inside userData that holds the meme files. */
export const MEME_DIR_NAME = 'memes'

/** The bundled sample, copied into the tray on a brand-new profile. */
export const SAMPLE_MEME_FILE = 'sample-meme.png'

/** The extension a mime type is stored under. */
export function extensionFor(mime: MemeMime): 'jpg' | 'png' {
  return mime === 'image/png' ? 'png' : 'jpg'
}

/**
 * The name a meme is stored under: <memeId>-<hash8>.<ext>. The hash makes
 * the URL immutable, so it can be cached forever and a re-upload never
 * serves a stale image.
 */
export function memeFileName(memeId: string, bytes: Uint8Array, mime: MemeMime): string {
  const hash = createHash('sha256').update(bytes).digest('hex').slice(0, 8)
  return `${memeId}-${hash}.${extensionFor(mime)}`
}

/** A meme together with where its bytes live on disk. */
export interface MemeAsset {
  id: string
  fileName: string
  mime: MemeMime
  width: number
  height: number
  byteSize: number
  /** The absolute path of the file. */
  filePath: string
}

/**
 * The meme files on disk, tied to the SQLite metadata. The files live in
 * <userData>/memes, the rows in the app database.
 */
export class MemeAssets {
  constructor(
    readonly store: MemeStore,
    readonly dir: string
  ) {}

  /** Creates the meme folder when it is missing. */
  ensure(): void {
    mkdirSync(this.dir, { recursive: true })
  }

  /** The meme behind a file name, or null when there is none. */
  byFileName(fileName: string): MemeAsset | null {
    if (!MEME_FILE_PATTERN.test(fileName)) return null
    const row = this.store.getByFileName(fileName)
    return row ? this.toAsset(row) : null
  }

  /** The meme behind its id, or null when unknown. */
  byId(id: string): MemeAsset | null {
    const row = this.store.get(id)
    return row ? this.toAsset(row) : null
  }

  /** Writes the bytes and returns the file name they landed under. */
  write(memeId: string, bytes: Uint8Array, mime: MemeMime): string {
    this.ensure()
    const fileName = memeFileName(memeId, bytes, mime)
    writeFileSync(join(this.dir, fileName), bytes)
    return fileName
  }

  /** Removes a file; a missing file is not an error. */
  remove(fileName: string): void {
    rmSync(join(this.dir, fileName), { force: true })
  }

  /** The bytes of a file, or null when it cannot be read. */
  read(fileName: string): Buffer | null {
    try {
      return readFileSync(join(this.dir, fileName))
    } catch {
      return null
    }
  }

  private toAsset(row: StoredMeme): MemeAsset {
    return {
      id: row.id,
      fileName: row.fileName,
      mime: row.mime,
      width: row.width,
      height: row.height,
      byteSize: row.byteSize,
      filePath: join(this.dir, row.fileName)
    }
  }
}

/**
 * The phone-facing payload of a pop, built from the stored meme. The path is
 * relative on purpose: the phone may have joined on another LAN address.
 * Returns null when the meme is unknown, so nothing is ever sent.
 */
export function buildPopPayload(
  store: MemeStore,
  memeId: string,
  durationMs: number
): MemePopPayload | null {
  const row = store.get(memeId)
  if (!row) return null
  return {
    memeId: row.id,
    path: `/memes/${row.fileName}`,
    mime: row.mime,
    width: row.width,
    height: row.height,
    durationMs: Math.min(MEME_MAX_DURATION_MS, Math.max(MEME_MIN_DURATION_MS, durationMs))
  }
}

/** The pixel size of a PNG, read from its IHDR chunk. */
export function pngSize(bytes: Buffer): { width: number; height: number } | null {
  // 8-byte signature, 4-byte length, "IHDR", then width and height.
  if (bytes.length < 24) return null
  if (bytes.readUInt32BE(0) !== 0x89504e47) return null
  if (bytes.toString('ascii', 12, 16) !== 'IHDR') return null
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20) }
}

/**
 * Finds the bundled sample meme. In development it sits in the project
 * folder; in a packaged app it is an extra resource next to the asar.
 */
export function findSampleMeme(dirs: string[]): string | null {
  for (const dir of dirs) {
    if (!dir) continue
    for (const candidate of [
      join(dir, 'resources', SAMPLE_MEME_FILE),
      join(dir, SAMPLE_MEME_FILE)
    ]) {
      if (existsSync(candidate)) return candidate
    }
  }
  return null
}

/**
 * Copies the bundled sample meme into the tray. Only ever called on a
 * brand-new profile, so deleting every meme never resurrects it.
 */
export function seedSampleMeme(assets: MemeAssets, dirs: string[]): StoredMeme | null {
  const source = findSampleMeme(dirs)
  if (!source) return null
  assets.ensure()
  let bytes: Buffer
  try {
    bytes = readFileSync(source)
  } catch {
    return null
  }
  const size = pngSize(bytes)
  if (!size) return null
  const id = randomUUID()
  const fileName = assets.write(id, bytes, 'image/png')
  const row = assets.store.insert({
    id,
    name: 'Sample meme',
    fileName,
    mime: 'image/png',
    width: size.width,
    height: size.height,
    byteSize: bytes.length,
    thumb: ''
  })
  return row
}
